-- Ads link for Grok (docs/monetization/grok-ads-api.md). Add-only.
-- Meta (Facebook and Instagram) only. Hard facts: total ad budget $300 (loaded $280, reserve $20), every ad ends Dec 8 2026, Meta account limit $280, county targeting only.
--   ads_campaigns  : one row per audience campaign (budget, dates). The budget is per audience campaign, not per ad: ads_items.budget_cents is 0 on purpose.
--   ads_items      : the approved ad copy, word for word from docs/marketing/ads-content.json. Copy and status change ONLY by a new migration, never through the API.
--   ads_reports    : the LATEST status Grok reported for each ad (counts and a status word; no personal data).
--   ads_report_log : every report received, append-only, pruned after 90 days by the report endpoint.
CREATE TABLE IF NOT EXISTS ads_campaigns (
  audience TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  platform TEXT NOT NULL DEFAULT 'meta' CHECK (platform = 'meta'),
  budget_cents INTEGER NOT NULL CHECK (budget_cents >= 0),
  starts TEXT NOT NULL,
  ends TEXT NOT NULL,
  wave INTEGER NOT NULL,
  daily_hint_cents INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS ads_items (
  id TEXT PRIMARY KEY,
  audience TEXT NOT NULL,
  platform TEXT NOT NULL DEFAULT 'meta' CHECK (platform = 'meta'),
  concept TEXT NOT NULL DEFAULT '',
  headline TEXT NOT NULL,
  primary_text TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  cta TEXT NOT NULL DEFAULT 'Learn more',
  landing_url TEXT NOT NULL,
  visual TEXT NOT NULL DEFAULT '',
  asset_id TEXT,
  wave INTEGER NOT NULL DEFAULT 0,
  budget_cents INTEGER NOT NULL DEFAULT 0,
  starts TEXT NOT NULL,
  ends TEXT NOT NULL,
  daily_hint_cents INTEGER NOT NULL DEFAULT 0,
  status TEXT NOT NULL CHECK (status IN ('approved','hold','rejected','not_in_launch'))
);
CREATE TABLE IF NOT EXISTS ads_reports (
  ad_id TEXT PRIMARY KEY,
  campaign TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('draft','in_review','active','paused','disapproved','ended')),
  spend_cents INTEGER NOT NULL DEFAULT 0,
  impressions INTEGER NOT NULL DEFAULT 0,
  clicks INTEGER NOT NULL DEFAULT 0,
  disapproval_reason TEXT NOT NULL DEFAULT '',
  as_of TEXT NOT NULL,
  received_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS ads_report_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  ad_id TEXT NOT NULL,
  campaign TEXT NOT NULL,
  status TEXT NOT NULL,
  spend_cents INTEGER NOT NULL DEFAULT 0,
  impressions INTEGER NOT NULL DEFAULT 0,
  clicks INTEGER NOT NULL DEFAULT 0,
  disapproval_reason TEXT NOT NULL DEFAULT '',
  as_of TEXT NOT NULL,
  received_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_ads_report_log_received ON ads_report_log (received_at);
CREATE INDEX IF NOT EXISTS idx_ads_report_log_ad ON ads_report_log (ad_id, id);

