INSERT INTO ads_items (id, audience, platform, concept, headline, primary_text, description, cta, landing_url, visual, asset_id, wave, budget_cents, starts, ends, daily_hint_cents, status) VALUES ('ev-a-meta', 'event_holders', 'meta', 'A: List it free', 'List your holiday event for free', 'Tree lighting, boat parade, market or light show in Southern California? Add it to the SoCal Lights map. Free to list.', 'Free to list', 'Learn more', 'https://socallights.app/add-event?ref=mt-ev-a&utm_source=meta&utm_medium=paid_social&utm_campaign=scl-ev-nov26&utm_content=a-listfree-v1', 'Real screenshot of a city page (/in/<city>) showing public events, 4:5. Public venues and event names only.', 'a02-city-page', 1, 0, '2026-11-12', '2026-12-01', 225, 'approved') ON CONFLICT(id) DO UPDATE SET audience = excluded.audience, concept = excluded.concept, headline = excluded.headline, primary_text = excluded.primary_text, description = excluded.description, cta = excluded.cta, landing_url = excluded.landing_url, visual = excluded.visual, asset_id = excluded.asset_id, wave = excluded.wave, budget_cents = excluded.budget_cents, starts = excluded.starts, ends = excluded.ends, daily_hint_cents = excluded.daily_hint_cents, status = excluded.status;
