INSERT INTO ads_items (id, audience, platform, concept, headline, primary_text, description, cta, landing_url, visual, asset_id, wave, budget_cents, starts, ends, daily_hint_cents, status) VALUES ('in-a-meta', 'installers', 'meta', 'A: Free company page', 'A free page for your lighting company', 'Installers: make a free SoCal Lights page with your areas, phone and website. It''s linked from homes you installed.', 'Free profile page', 'Learn more', 'https://socallights.app/add-house?kind=installer&ref=mt-in-a&utm_source=meta&utm_medium=paid_social&utm_campaign=scl-in-nov26&utm_content=a-page-v1', 'Real screenshot of an installer profile page. Use the live /installer/lights-up-today ONLY with that company''s written consent; otherwise a clearly labelled example profile. No customer names or addresses visible.', 'a05-installer-profile', 1, 0, '2026-11-12', '2026-11-23', 167, 'approved') ON CONFLICT(id) DO UPDATE SET audience = excluded.audience, concept = excluded.concept, headline = excluded.headline, primary_text = excluded.primary_text, description = excluded.description, cta = excluded.cta, landing_url = excluded.landing_url, visual = excluded.visual, asset_id = excluded.asset_id, wave = excluded.wave, budget_cents = excluded.budget_cents, starts = excluded.starts, ends = excluded.ends, daily_hint_cents = excluded.daily_hint_cents, status = excluded.status;
