INSERT INTO ads_items (id, audience, platform, concept, headline, primary_text, description, cta, landing_url, visual, asset_id, wave, budget_cents, starts, ends, daily_hint_cents, status) VALUES ('fa-e-meta', 'families', 'meta', 'E: Weekly lights email', 'Get the weekly lights email', 'A free weekly email from SoCal Lights with holiday lights and events near you. Choose your area and distance.', 'Free weekly email', 'Sign up', 'https://socallights.app/in/mission-viejo?ref=mt-fa-e&utm_source=meta&utm_medium=paid_social&utm_campaign=scl-fa-nov26&utm_content=e-email-v1', 'Real screenshot of the sign-up box on a city page (/in/<city>), 4:5. Do not use a real email example.', NULL, 0, 0, '2026-11-24', '2026-12-08', 667, 'not_in_launch') ON CONFLICT(id) DO UPDATE SET audience = excluded.audience, concept = excluded.concept, headline = excluded.headline, primary_text = excluded.primary_text, description = excluded.description, cta = excluded.cta, landing_url = excluded.landing_url, visual = excluded.visual, asset_id = excluded.asset_id, wave = excluded.wave, budget_cents = excluded.budget_cents, starts = excluded.starts, ends = excluded.ends, daily_hint_cents = excluded.daily_hint_cents, status = excluded.status;
